16: /// `GET /_xerj-console/api/v1/cluster/info`
17: ///
18: /// Returns enough for the SPA to:
19: /// - Show "node up since…" without a separate /uptime fetch.
20: /// - Render `mode == "standalone"` (single-node card, hide topology
21: ///   widget) or `mode == "raft"` (will light up `/cluster/raft` etc.
22: ///   in phase 4 — until then the SPA falls back to standalone view).
23: pub async fn info(State(state): State<ConsoleState>) -> ConsoleResult<Response> {
24:     use crate::state::ClusterMode;
25: 
26:     let mode = match state.cluster_mode {
27:         ClusterMode::Standalone => "standalone",
28:         ClusterMode::Raft => "raft",
29:     };
30: 
31:     Ok(ok(info_body(mode, state.started_at.0), None))
32: }
