34: /// Build the unauthenticated `cluster/info` body.
35: ///
36: /// AUTHZ-2: this endpoint is unauthenticated (the SPA reads it at boot, before
37: /// login, to choose standalone-vs-topology view). It must therefore expose only
38: /// what that decision needs — `mode` — plus the benign uptime. `node_id` and
39: /// the exact build `version` are deliberately omitted: a pre-auth version string
40: /// hands an attacker a precise target for known-CVE matching, and the node
41: /// identity leaks cluster topology. Authenticated callers get the full detail
42: /// from the credentialed cluster/status paths.
43: fn info_body(mode: &str, started_at_ms: i64) -> serde_json::Value {
44:     json!({
45:         "mode":          mode,
46:         "started_at_ms": started_at_ms,
47:     })
48: }
